'use strict';

// MODULES //

var fromWords = require( '@stdlib/number-float64-base-from-words' );
var toWords = require( '@stdlib/number-float64-base-to-words' );


// MAIN //

/**
* Returns the next representable double-precision floating-point number greater than the input value.
*
* ## Notes
*
* -   The input value is assumed to be a nonnegative finite number, as these are the only values arising in the root-finding brackets of this package.
*
* @private
* @param {NonNegativeNumber} x - input value
* @returns {number} next representable value toward positive infinity
*/
function floatNext( x ) {
	var w;

	w = toWords( x );
	if ( w[ 1 ] === 0xffffffff ) {
		w[ 0 ] += 1;
		w[ 1 ] = 0;
	} else {
		w[ 1 ] += 1;
	}
	return fromWords( w[ 0 ], w[ 1 ] );
}


// EXPORTS //

module.exports = floatNext;
